import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import type { PayrollRun } from "../src/payroll/bankFile.ts";
import type { SftpConnector } from "../src/payroll/sftp.ts";
import { uploadPaymentFile } from "../src/payroll/uploader.ts";
import { uploadApprovedRuns } from "../src/payroll/batch.ts";

// Fake bank SFTP server that counts open sessions and remote file handles.
// dropFor: employers whose connection breaks after the first write (later writes and the close fail).
// flushFailFor: employers whose file fails to flush on close (the handle is still released).
function fakeBank(options: { maxSessions?: number; dropFor?: string[]; flushFailFor?: string[] } = {}) {
    const { maxSessions = 2, dropFor = [], flushFailFor = [] } = options;
    const bank = { openSessions: 0, openFiles: 0, connects: 0, files: new Map<string, string>() };
    const connector: SftpConnector = {
        async connect() {
            await tick();
            bank.connects++;
            if (bank.openSessions >= maxSessions) throw new Error("SSH_MSG_DISCONNECT: too many sessions for user");
            bank.openSessions++;
            let sessionOpen = true;
            return {
                async openWrite(path) {
                    await tick();
                    bank.openFiles++;
                    const dropped = dropFor.some((id) => path.includes(`/${id}-`));
                    const flushFails = flushFailFor.some((id) => path.includes(`/${id}-`));
                    let open = true;
                    let writes = 0;
                    let content = "";
                    return {
                        async write(data) {
                            await tick();
                            if (dropped && ++writes > 1) throw new Error("write ECONNRESET");
                            content += data;
                        },
                        async close() {
                            if (!open) return;
                            open = false;
                            bank.openFiles--;
                            await tick();
                            if (dropped) throw new Error("close failed: connection is gone");
                            if (flushFails) throw new Error("flush failed: quota exceeded");
                            bank.files.set(path, content);
                        },
                    };
                },
                async rename(from, to) {
                    const content = bank.files.get(from);
                    if (content === undefined) throw new Error(`no such file ${from}`);
                    bank.files.delete(from);
                    bank.files.set(to, content);
                },
                async close() {
                    if (!sessionOpen) return;
                    sessionOpen = false;
                    bank.openSessions--;
                },
            };
        },
    };
    return { bank, connector };
}

const target = { host: "sftp.bank.example", user: "acme-payroll", dir: "/inbound" };
const run = (employerId: string, runId = "2026-11"): PayrollRun => ({
    employerId,
    runId,
    payDate: "2026-11-28",
    payments: [
        { employeeId: "e1", name: "Grace Hopper", iban: "DE89370400440532013000", amountCents: 412_500 },
        { employeeId: "e2", name: "Alan Turing", iban: "GB29NWBK60161331926819", amountCents: 398_000 },
    ],
});

test("a payroll run is uploaded under its final name with header, payments and trailer", async () => {
    const { bank, connector } = fakeBank();
    const result = await uploadPaymentFile(connector, target, run("acme"));
    assert.deepEqual(result, { path: "/inbound/acme-2026-11.pay", lines: 4 });
    assert.deepEqual(bank.files.get("/inbound/acme-2026-11.pay")?.split("\n"), [
        "H|acme|2026-11|20261128",
        "P|e1|DE89370400440532013000|412500|Grace Hopper",
        "P|e2|GB29NWBK60161331926819|398000|Alan Turing",
        "T|2|810500",
        "",
    ]);
});

test("an invalid run is rejected before connecting to the bank", async () => {
    const { bank, connector } = fakeBank();
    const bad = { ...run("acme"), payments: [{ employeeId: "e9", name: "X", iban: "nope", amountCents: 10 }] };
    await assert.rejects(uploadPaymentFile(connector, target, bad), /e9: IBAN is invalid/);
    assert.equal(bank.connects, 0);
});

test("a successful upload leaves no session or file handle open", async () => {
    const { bank, connector } = fakeBank();
    await uploadPaymentFile(connector, target, run("acme"));
    assert.deepEqual([bank.openSessions, bank.openFiles], [0, 0]);
});

test("a connection that breaks mid-upload still has its session closed", async () => {
    const { bank, connector } = fakeBank({ dropFor: ["globex"] });
    await assert.rejects(uploadPaymentFile(connector, target, run("globex")));
    assert.deepEqual({ sessions: bank.openSessions, files: bank.openFiles }, { sessions: 0, files: 0 });
});

test("when a write fails, the caller sees the write error", async () => {
    const { connector } = fakeBank({ dropFor: ["globex"] });
    await assert.rejects(uploadPaymentFile(connector, target, run("globex")), /ECONNRESET/);
});

test("broken uploads don't stop the other employers from being paid", async () => {
    const { bank, connector } = fakeBank({ maxSessions: 2, dropFor: ["globex", "initech"] });
    const report = await uploadApprovedRuns(connector, target, [run("globex"), run("initech"), run("acme"), run("umbrella")]);
    console.log("nightly report:", JSON.stringify(report, null, 2), "\nsessions still open:", bank.openSessions);
    assert.deepEqual(report.uploaded, ["/inbound/acme-2026-11.pay", "/inbound/umbrella-2026-11.pay"]);
    assert.deepEqual(report.failed.map((f) => f.runId), ["2026-11", "2026-11"]);
});

test("a file that fails to flush is reported, not renamed, and leaves nothing open", async () => {
    const { bank, connector } = fakeBank({ flushFailFor: ["acme"] });
    await assert.rejects(uploadPaymentFile(connector, target, run("acme")), /quota exceeded/);
    assert.equal(bank.files.has("/inbound/acme-2026-11.pay"), false);
    assert.deepEqual([bank.openSessions, bank.openFiles], [0, 0]);
});
